import type { FilterExpression } from '@wix/sdk-types'
import type {
  WixDataBulkRemoveOptions,
  WixDataItem,
  WixDataQuerySpec,
} from './types'

/**
 * Options builder for bulk remove operations.
 *
 * Use this builder to configure bulk remove behavior such as hooks suppression,
 * and conditional removal.
 * @public
 * @builder
 * @documentationMaturity preview
 */
export interface WixDataBulkRemoveOptionsBuilder {
  /**
   * Sets whether to suppress bulk remove hooks.
   *
   * When `true`, the bulk remove runs without triggering hooks.
   */
  withSuppressHooks(value: boolean): WixDataBulkRemoveOptionsBuilder
  /**
   * Sets whether to include draft items when removing items in bulk.
   * @internal
   */
  withShowDrafts(value: boolean): WixDataBulkRemoveOptionsBuilder
  /**
   * Sets the condition that determines which items to remove.
   */
  withCondition(
    value: FilterExpression<WixDataItem, WixDataQuerySpec>
  ): WixDataBulkRemoveOptionsBuilder
  /**
   * Builds the bulk remove options object.
   */
  build(): WixDataBulkRemoveOptions
}

class WixDataBulkRemoveOptionsBuilderImpl
  implements WixDataBulkRemoveOptionsBuilder
{
  constructor(private readonly options: WixDataBulkRemoveOptions = {}) {}

  withSuppressHooks(value: boolean): WixDataBulkRemoveOptionsBuilder {
    return this.copy({ suppressHooks: value })
  }

  withShowDrafts(value: boolean): WixDataBulkRemoveOptionsBuilder {
    return this.copy({ showDrafts: value })
  }

  withCondition(
    value: FilterExpression<WixDataItem, WixDataQuerySpec>
  ): WixDataBulkRemoveOptionsBuilder {
    return this.copy({ condition: value.filter })
  }

  build(): WixDataBulkRemoveOptions {
    return {
      ...this.options,
    }
  }

  private copy(
    options: WixDataBulkRemoveOptions
  ): WixDataBulkRemoveOptionsBuilder {
    return new WixDataBulkRemoveOptionsBuilderImpl({
      ...this.options,
      ...options,
    })
  }
}

/**
 * Creates a new bulk remove options builder.
 * @public
 * @documentationMaturity preview
 *
 * @example
 * ```ts title="Create a bulk remove options builder"
 * import { items, BulkRemoveOptionsBuilder, Filter } from '@wix/data'
 *
 * const options = BulkRemoveOptionsBuilder()
 *   .withSuppressHooks(true)
 *   .withCondition(Filter('status').eq('active'))
 *   .build()
 *
 * const result = await items.bulkRemove('myCollection', ['item-1', 'item-2'], options)
 * ```
 */
export const BulkRemoveOptionsBuilder: () => WixDataBulkRemoveOptionsBuilder =
  () => new WixDataBulkRemoveOptionsBuilderImpl()
